package com.tradepilot.survival.entity;
import com.tradepilot.entity.*; import com.tradepilot.survival.ProtectionCommitmentStatus; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="next_session_protection_evaluations", uniqueConstraints=@UniqueConstraint(name="uk_protection_evaluation_fingerprint",columnNames={"commitment_id","source_fingerprint"}))
public class NextSessionProtectionEvaluation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY, optional=false) @JoinColumn(name="user_id", nullable=false) private User user; @ManyToOne(fetch=FetchType.LAZY, optional=false) @JoinColumn(name="account_id", nullable=false) private TradingAccount account; @ManyToOne(fetch=FetchType.LAZY, optional=false) @JoinColumn(name="commitment_id", nullable=false) private NextSessionProtectionCommitment commitment; @Column(nullable=false) private LocalDate evaluatedSessionDate; @Enumerated(EnumType.STRING) @Column(nullable=false,length=32) private ProtectionCommitmentStatus overallStatus; @Column(nullable=false,length=128) private String sourceFingerprint; @Column(nullable=false,length=40) private String evaluationVersion; @Column(nullable=false) private Integer evidenceCoverage; @Column(nullable=false) private Boolean isCurrent=true; @Column(nullable=false) private LocalDateTime createdAt; @Column(nullable=false) private LocalDateTime updatedAt; @PrePersist void c(){var n=LocalDateTime.now();createdAt=n;updatedAt=n;} @PreUpdate void u(){updatedAt=LocalDateTime.now();}
public Long getId(){return id;} public LocalDate getEvaluatedSessionDate(){return evaluatedSessionDate;} public ProtectionCommitmentStatus getOverallStatus(){return overallStatus;} public String getEvaluationVersion(){return evaluationVersion;} public Integer getEvidenceCoverage(){return evidenceCoverage;} public Boolean getIsCurrent(){return isCurrent;} public void setUser(User v){user=v;} public void setAccount(TradingAccount v){account=v;} public void setCommitment(NextSessionProtectionCommitment v){commitment=v;} public void setEvaluatedSessionDate(LocalDate v){evaluatedSessionDate=v;} public void setOverallStatus(ProtectionCommitmentStatus v){overallStatus=v;} public void setSourceFingerprint(String v){sourceFingerprint=v;} public void setEvaluationVersion(String v){evaluationVersion=v;} public void setEvidenceCoverage(Integer v){evidenceCoverage=v;} public void setIsCurrent(Boolean v){isCurrent=v;} }
